@startuml
abstract class Zahlung {
  - betrag : Decimal
  + ausfuehren() : Boolean
}

class Kreditkartenzahlung {
  - kartenende : String
  - kartenanbieter : String
}

class Ueberweisung {
  - iban : String
  - kontoinhaber : String
}

class Bestellung {
  - nummer : String
  - bestelldatum : Date
  - status : String
}

class Bestellposition {
  - menge : Integer
  - einzelpreis : Decimal
}

class Produkt {
  - artikelnummer : String
  - bezeichnung : String
  - verkaufspreis : Decimal
}

Zahlung <|-- Kreditkartenzahlung
Zahlung <|-- Ueberweisung
Bestellung "1" *-- "1..*" Bestellposition : besteht aus
Bestellposition "0..*" --> "1" Produkt : bezieht sich auf
Bestellung "1" --> "1" Zahlung : bezahlt mit
@enduml

@startuml
abstract class Benutzer {
  - id : Integer
  - name : String
  - email : String
}

class Kunde {
  - kundennummer : String
}

class SupportMitarbeiter {
  - kuerzel : String
  - supportLevel : Integer
}

class Ticket {
  - betreff : String
  - beschreibung : String
  - status : String
  - prioritaet : String
}

class Kategorie {
  - name : String
  - beschreibung : String
}

class Kommentar {
  - text : String
  - erstelltAm : DateTime
}

Benutzer <|-- Kunde
Benutzer <|-- SupportMitarbeiter
Kunde "1" --> "0..*" Ticket : meldet
Ticket "0..*" --> "0..1" SupportMitarbeiter : zugewiesen an
Kategorie "1" <-- "0..*" Ticket : gehoert zu
Ticket "1" *-- "0..*" Kommentar : enthaelt
Kommentar "0..*" --> "1" Benutzer : erstellt von
@enduml

@startuml
abstract class Person {
  - name : String
  - email : String
}

class Teilnehmer {
  - teilnehmernummer : String
}

class Dozent {
  - kuerzel : String
  - fachgebiet : String
}

class Kurs {
  - kursnummer : String
  - titel : String
  - startdatum : Date
  - enddatum : Date
}

class Anmeldung {
  - anmeldedatum : Date
  - status : String
}

class Pruefung {
  - pruefungsdatum : Date
  - pruefungsart : String
  - maximalePunktzahl : Integer
}

class Pruefungsleistung {
  - erreichtePunkte : Integer
  - note : String
}

Person <|-- Teilnehmer
Person <|-- Dozent
Dozent "1" --> "0..*" Kurs : leitet
Teilnehmer "1" --> "0..*" Anmeldung : meldet sich an
Kurs "1" --> "0..*" Anmeldung : besitzt
Kurs "1" *-- "0..*" Pruefung : enthaelt
Teilnehmer "1" --> "0..*" Pruefungsleistung : erzielt
Pruefung "1" --> "0..*" Pruefungsleistung : wird bewertet durch
@enduml

@startuml
start
:Stoerung im Supportportal melden;

while (Pflichtangaben vollstaendig?) is (nein)
  :Fehlende Angaben anfordern;
  :Mitarbeiter ergaenzt Meldung;
endwhile (ja)

:Ticket erstellen;
:Kategorie und Prioritaet bestimmen;
:Supportgruppe zuordnen;
:Ticket uebernehmen;

if (Bekannte Loesung vorhanden?) then (ja)
  :Bekannte Loesung anwenden;
else (nein)
  :Ursache analysieren;

  while (Zusatzinformationen noetig?) is (ja)
    :Rueckfrage an Mitarbeiter senden;
    :Antwort abwarten;
    :Antwort pruefen;
  endwhile (nein)

  if (Im First-Level loesbar?) then (ja)
    :Loesung umsetzen;
  else (nein)
    :An Second-Level-Support eskalieren;
    :Problem im Second-Level analysieren;
    :Loesung erarbeiten und umsetzen;
  endif
endif

:Loesung dokumentieren;
:Mitarbeiter informieren;

if (Stoerung behoben?) then (ja)
  :Ticket schliessen;
else (nein)
  :Ticket erneut oeffnen;
  :Nachbearbeitung starten;
  :Loesung korrigieren;
  :Ticket schliessen;
endif

stop
@enduml
